# range(5) gera uma sequência de 0 até 4 (5 números!)
for i in range(5):
    print(f"Execução número {i}")

# break: interrompe o loop imediatamente
for n in range(10):
    if n == 5:
        break
    print(n)  # Imprime de 0 a 4

# continue: pula para a próxima iteração
for n in range(5):
    if n == 2:
        continue
    print(n)  # Imprime 0, 1, 3, 4 (pula o 2!)
